import * as T from 'three';
import {PARTS} from './catalog.js';
export function validateCraft(value){if(!value||value.version!==1||!Array.isArray(value.parts)||!value.parts.length||value.parts.length>400)throw Error('機体形式または部品数が不正です（1〜400部品）。');const ids=new Set();for(const p of value.parts){if(!PARTS[p.type]||typeof p.id!=='string'||ids.has(p.id)||!['p','r'].every(k=>Array.isArray(p[k])&&p[k].length===3&&p[k].every(n=>Number.isFinite(n)&&Math.abs(n)<10000))||!Number.isInteger(p.stage)||p.stage<0||p.stage>9)throw Error('部品データが不正です。');ids.add(p.id);}for(const p of value.parts){if(p.parent&&!ids.has(p.parent))throw Error('接続先が見つかりません。');const seen=new Set([p.id]);let n=p;while(n.parent){if(seen.has(n.parent))throw Error('接続に循環があります。');seen.add(n.parent);n=value.parts.find(x=>x.id===n.parent);}}return structuredClone(value.parts);}
export function descendants(parts,id){const set=new Set([id]);let change=true;while(change){change=false;for(const p of parts)if(set.has(p.parent)&&!set.has(p.id)){set.add(p.id);change=true;}}return set;}
export function statistics(parts,fuelRatio=1,ballast=0){let mass=0,dry=0,fuel=0,thrust=0,weightedIsp=0;const com=new T.Vector3();for(const p of parts){const d=PARTS[p.type],m=d.mass+(d.fuel||0)*fuelRatio+(d.ballast||0)*ballast;mass+=m;dry+=d.mass;fuel+=d.fuel||0;thrust+=d.thrust||0;weightedIsp+=(d.thrust||0)*(d.isp||0);com.addScaledVector(new T.Vector3(...p.p),m);}com.divideScalar(mass||1);const isp=weightedIsp/(thrust||1);return {mass,dry,fuel,thrust,com,twr:thrust/(mass*9.81),dv:fuel?isp*9.81*Math.log(mass/(dry+ballast*parts.reduce((s,p)=>s+(PARTS[p.type].ballast||0),0))):0};}
const up=new T.Vector3(0,1,0);
function extentY(p,q=new T.Quaternion()){const d=PARTS[p.type],rot=new T.Matrix4().makeRotationFromQuaternion(q.clone().multiply(new T.Quaternion().setFromEuler(new T.Euler(...p.r)))),e=rot.elements;return (Math.abs(e[1])*d.size[0]+Math.abs(e[5])*d.size[1]+Math.abs(e[9])*d.size[2])/2;}
export class Flight {
 constructor(parts,environment){this.parts=structuredClone(parts);this.environment=environment;this.q=new T.Quaternion();this.pos=new T.Vector3();this.vel=new T.Vector3();this.omega=new T.Vector3();this.fuelRatio=1;this.ballast=0;this.throttle=0;this.sas=true;this.brake=true;this.time=0;this.stage=-1;this.crashed=false;this.started=false;this.maxAltitude=0;this.stats=statistics(parts);this.floor=-Math.min(...parts.map(p=>p.p[1]-extentY(p)));this.pos.y=environment==='water'?-.35:this.floor+.05;this.active=new Set();this.lastThrust=0;this.detached=[];}
 stageNext(){this.stage++;this.started=true;this.brake=false;for(const p of this.parts)if(p.stage===this.stage&&PARTS[p.type].thrust)this.active.add(p.id);let remove=new Set();for(const p of this.parts)if(PARTS[p.type].decoupler&&p.stage===this.stage)for(const id of descendants(this.parts,p.id))remove.add(id);if(remove.size){this.detached.push(...this.parts.filter(p=>remove.has(p.id)));this.parts=this.parts.filter(p=>!remove.has(p.id));for(const p of this.parts)if(remove.has(p.parent))p.parent=null;}return remove;}
 step(dt,input={}){if(this.crashed||!this.parts.length)return;this.time+=dt;const st=statistics(this.parts,this.fuelRatio,this.ballast);this.stats=st;const mass=st.mass;const worldCom=st.com.clone().applyQuaternion(this.q).add(this.pos);const force=new T.Vector3(0,-mass*9.81,0),torque=new T.Vector3();const density=1.225*Math.exp(-Math.max(0,this.pos.y)/8500);let flow=0;this.lastThrust=0;let contacts=0;const cap=this.parts.reduce((s,p)=>s+(PARTS[p.type].fuel||0),0),wheelCount=this.parts.filter(p=>PARTS[p.type].wheel).length;const apply=(f,r)=>{force.add(f);torque.add(r.clone().cross(f));};const localForward=new T.Vector3(0,0,1).applyQuaternion(this.q);let inertia=0;
 for(const p of this.parts){const d=PARTS[p.type],r=new T.Vector3(...p.p).sub(st.com).applyQuaternion(this.q),wp=r.clone().add(worldCom),pq=new T.Quaternion().setFromEuler(new T.Euler(...p.r)),orientation=this.q.clone().multiply(pq),axis=up.clone().applyQuaternion(orientation);inertia+=(d.mass+(d.fuel||0)*this.fuelRatio+(d.ballast||0)*this.ballast)*(r.lengthSq()+.3);const pv=this.vel.clone().add(this.omega.clone().cross(r));
 if(this.started&&d.thrust&&this.active.has(p.id)&&(d.water||cap>0&&this.fuelRatio>0)){let f=d.thrust*this.throttle;if(d.air)f*=density/1.225;if(d.water)f*=this.environment==='water'?T.MathUtils.clamp((.1-wp.y)/.25,0,1):0;apply(axis.multiplyScalar(f),r);if(!d.water)flow+=f/(d.isp*9.81);this.lastThrust+=f;}
 if(d.wing){const normal=new T.Vector3(0,0,1).applyQuaternion(orientation),forward=up.clone().applyQuaternion(orientation),speed=pv.length();if(speed>1){const aoa=Math.atan2(-pv.dot(normal),Math.abs(pv.dot(forward))+.1);const cl=T.MathUtils.clamp(aoa*4.5,-1.2,1.2);const lift=normal.multiplyScalar(.5*density*speed*speed*d.wing*cl);apply(lift,r);force.addScaledVector(pv,-.5*density*speed*d.wing*(.025+.06*cl*cl));}}
 if(this.environment==='water'){const volume=d.volume||d.size[0]*d.size[1]*d.size[2]*.18;for(const u of [-.32,.32]){const offset=new T.Vector3(0,d.size[1]*u,0).applyQuaternion(orientation),rr=r.clone().add(offset),point=worldCom.clone().add(rr),velocity=this.vel.clone().add(this.omega.clone().cross(rr));const depth=Math.max(.12,extentY(p,this.q)*2*.6),submerged=T.MathUtils.clamp((depth/2-point.y)/depth,0,1);apply(new T.Vector3(0,1000*9.81*volume*.5*submerged,0),rr);apply(velocity.multiplyScalar(-submerged*volume*500),rr);}}
 if(d.wheel&&this.environment!=='water'){const bottom=wp.y-.35;if(bottom<.18){contacts++;const share=mass/Math.max(1,wheelCount),spring=Math.max(0,(.18-bottom)*share*130-pv.y*share*9);apply(new T.Vector3(0,spring,0),r);const side=new T.Vector3(1,0,0).applyQuaternion(this.q);if(this.started&&!this.brake){const motor=this.parts.some(p=>PARTS[p.type].thrust)?0:1;force.addScaledVector(localForward,motor*this.throttle*share*3*Math.max(0,1-Math.abs(pv.dot(localForward))/18));}force.addScaledVector(side,-pv.dot(side)*share*5);force.addScaledVector(localForward,-pv.dot(localForward)*share*(this.brake?8:.008));}}
 }
 const speed=this.vel.length();force.addScaledVector(this.vel,-.5*density*.4*Math.max(1,this.parts.length*.16)*speed);if(cap)this.fuelRatio=Math.max(0,this.fuelRatio-flow*dt/cap);
 const control=this.parts.some(p=>PARTS[p.type].control),steering=new T.Vector3(input.pitch||0,input.yaw||0,input.roll||0);
 if(control&&this.started){torque.add(steering.clone().applyQuaternion(this.q).multiplyScalar(mass*12));}
 if(!this.holdQ||steering.lengthSq()>0||!this.sas)this.holdQ=this.q.clone();
 if(this.sas&&control){const error=this.holdQ.clone().multiply(this.q.clone().invert());if(error.w<0){error.x*=-1;error.y*=-1;error.z*=-1;error.w*=-1;}const correction=new T.Vector3(error.x,error.y,error.z).multiplyScalar(8*Math.max(inertia,mass));correction.clampLength(0,mass*15);torque.add(correction);torque.addScaledVector(this.omega,-Math.max(inertia,mass)*3);}
 torque.addScaledVector(this.omega,-inertia*.06);this.omega.addScaledVector(torque,dt/Math.max(mass*.4,inertia));this.omega.clampLength(0,2);const angle=this.omega.length()*dt;if(angle>0)this.q.premultiply(new T.Quaternion().setFromAxisAngle(this.omega.clone().normalize(),angle)).normalize();this.vel.addScaledVector(force,dt/mass);worldCom.addScaledVector(this.vel,dt);this.pos.copy(worldCom).sub(st.com.clone().applyQuaternion(this.q));
 if(this.environment!=='water'){let lowest=Infinity;for(const p of this.parts){const d=PARTS[p.type],center=new T.Vector3(...p.p).applyQuaternion(this.q).add(this.pos);const half=new T.Vector3(...d.size).multiplyScalar(.5);const rot=new T.Matrix4().makeRotationFromQuaternion(this.q.clone().multiply(new T.Quaternion().setFromEuler(new T.Euler(...p.r))));const e=rot.elements;const extent=Math.abs(e[1])*half.x+Math.abs(e[5])*half.y+Math.abs(e[9])*half.z;lowest=Math.min(lowest,center.y-extent);}if(lowest<0){if(this.vel.y < -9&&this.time>.5){this.crashed=true;return;}this.pos.y-=lowest;this.vel.y=Math.max(0,this.vel.y);if(!contacts){this.vel.x*=.96;this.vel.z*=.96;}}}
 this.maxAltitude=Math.max(this.maxAltitude,this.pos.y-this.floor);}
}
